package com.android.settings.notification;
import android.app.AlertDialog;import android.content.Context;import android.media.AudioManager;import android.os.*;import android.provider.Settings;import android.util.Log;import androidx.preference.Preference;
public final class LunatikTouchSoundPreference {
 static final String KEY="lunatik_touch_sound";
 static int value(Context c){return Math.max(0,Math.min(2,Settings.Global.getInt(c.getContentResolver(),KEY,0)));}
 public static void attach(Object fragment){try{Context c=(Context)fragment.getClass().getMethod("getContext").invoke(fragment);boolean ru=c.getResources().getConfiguration().getLocales().get(0).getLanguage().equals("ru");String[] names={ru?"Infinity (по умолчанию)":"Infinity (default)","Xiaomi","AOSP"};Object group=fragment.getClass().getMethod("findPreference",CharSequence.class).invoke(fragment,"system_sounds_and_vibrations_category");if(group==null)group=fragment.getClass().getMethod("getPreferenceScreen").invoke(fragment);Preference p=new Preference(c);p.setKey(KEY);p.setPersistent(false);p.setOrder(-29);p.setTitle(ru?"Звук нажатий":"Touch sound");p.setSummary(names[value(c)]);p.setOnPreferenceClickListener(pref->{new AlertDialog.Builder(c).setTitle(ru?"Звук нажатий":"Touch sound").setSingleChoiceItems(names,value(c),(dialog,which)->{Settings.Global.putInt(c.getContentResolver(),KEY,which);p.setSummary(names[which]);dialog.dismiss();try{AudioManager audio=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);audio.unloadSoundEffects();audio.loadSoundEffects();if(Settings.System.getInt(c.getContentResolver(),"sound_effects_enabled",0)!=0)new Handler(Looper.getMainLooper()).postDelayed(()->audio.playSoundEffect(AudioManager.FX_KEY_CLICK),600);}catch(Exception e){Log.w("LunatikTouchSoundPreference","Reload",e);}}).setNegativeButton(android.R.string.cancel,null).show();return true;});group.getClass().getMethod("addPreference",Preference.class).invoke(group,p);}catch(Exception e){Log.w("LunatikTouchSoundPreference","Attach",e);}}
}
